import json

import pytest

from pydantic import BaseModel, ConfigDict, PrivateAttr, TypeAdapter, ValidationError


class ServiceConfig(BaseModel):
    model_config = ConfigDict(extra='forbid')

    endpoint: str
    retries: int = 2
    _access_token: str = PrivateAttr()


def test_private_runtime_value_is_not_serialized():
    config = ServiceConfig.model_validate(
        {'endpoint': 'https://service.invalid', 'retries': 3},
        extra='forbid',
    )
    config._access_token = 'runtime-only-value'

    assert config.model_dump() == {'endpoint': 'https://service.invalid', 'retries': 3}
    assert config.model_dump(mode='json', serialize_as_any=True) == {
        'endpoint': 'https://service.invalid',
        'retries': 3,
    }
    assert 'runtime-only-value' not in json.dumps(config.model_dump())


def test_extra_credential_shaped_input_fails_before_model_creation():
    adapter = TypeAdapter(ServiceConfig)

    with pytest.raises(ValidationError, match='access_token'):
        adapter.validate_python(
            {
                'endpoint': 'https://service.invalid',
                'access_token': 'unexpected-input',
            },
            extra='forbid',
        )

    validated = adapter.validate_python(
        {'endpoint': 'https://service.invalid', 'retries': 1},
        extra='forbid',
    )
    assert validated.model_dump() == {'endpoint': 'https://service.invalid', 'retries': 1}
